//! 🧪️ The same initiating caller owns core planning and native child translation.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation};
use std::sync::Arc;
fn clock()->Option<u64>{Some(1000)}
fn native<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn source(operation:&str)->semio_framework_artifact_flow_flow::FlowHostSnapshot{let mut source=semio_framework_artifact_flow_flow::FlowHostSnapshot{schema:String::new(),camera:semio_framework_artifact_flow_flow::CameraJson{x:0.0,y:0.0,zoom:1.0},widgets:vec![Widget::OutputAction{id:"sink".into(),action:String::new()},Widget::InputNote{id:"b".into(),text:"B".into()},Widget::InputSlider{id:"a".into(),label:"A".into(),value:1.0,min:0.0,max:10.0,step:1.0}],synapses:vec![semio_framework_artifact_flow_flow::SynapseSpec{id:"s101".into(),from:"a".into(),from_port:"number".into(),to:"sink".into(),to_port:String::new()}],layout:Default::default()};source.layout.insert("a".into(),WidgetLayout{x:20.0,y:30.0});if operation.starts_with("insert"){let input=operation=="insert-input";source.widgets.push(Widget::Neuron{id:"variadic".into(),neuron_kind:"law.variadic".into(),params:Default::default(),input_ports:vec!["old".into()],output_ports:vec!["old".into()],preview:true});source.synapses.push(if input{semio_framework_artifact_flow_flow::SynapseSpec{id:"shift".into(),from:"a".into(),from_port:"number".into(),to:"variadic".into(),to_port:"0".into()}}else{semio_framework_artifact_flow_flow::SynapseSpec{id:"shift".into(),from:"variadic".into(),from_port:"0".into(),to:"sink".into(),to_port:String::new()}})}source}
#[test]
fn original_authoring_to_native_child_matches_genuine_all_six_operations_and_cancellation(){
 for operation in ["connect","disconnect","remove","add","insert-input","insert-output","reorganize"]{
  let source=source(operation);let info=flow::neural::OperatorInfo{id:"law.variadic".into(),extension:"law".into(),name:"Variadic".into(),abbreviation:String::new(),icon:String::new(),summary:String::new(),inputs:Vec::new(),outputs:Vec::new(),variadic_input:Some(flow::neural::VariadicSpec{slot_key:"input".into(),min:0,max:Some(10)}),variadic_output:Some(flow::neural::VariadicSpec{slot_key:"output".into(),min:0,max:Some(10)}),group:Vec::new()};let infos=Arc::new([(info.id.clone(),info)].into_iter().collect());let descriptor=semio_framework_artifact_flow_flow::WidgetDescriptor::InputNote{id:None,text:Some("new".into())};let options=infinite_canvas::board::schema::layout::DagLayoutOptions::default();let(mode,request)=match operation{
   "connect"=>(FlowLeafMode::Connect,flow::FlowAuthoringRequest::ConnectPorts{from:"b",from_port:"text",to:"sink",to_port:""}),
   "disconnect"=>(FlowLeafMode::Disconnect,flow::FlowAuthoringRequest::Disconnect{id:"s101"}),
   "remove"=>(FlowLeafMode::Remove,flow::FlowAuthoringRequest::RemoveWidget{id:"a"}),
   "add"=>(FlowLeafMode::Add{x:42.0,y:13.0},flow::FlowAuthoringRequest::AddWidget{descriptor:&descriptor,x:42.0,y:13.0}),
   "insert-input"=>(FlowLeafMode::Insert{input:true},flow::FlowAuthoringRequest::InsertPort{id:"variadic",input:true,index:0}),
   "insert-output"=>(FlowLeafMode::Insert{input:false},flow::FlowAuthoringRequest::InsertPort{id:"variadic",input:false,index:0}),
   "reorganize"=>(FlowLeafMode::Reorganize,flow::FlowAuthoringRequest::Reorganize{options:&options}),_=>unreachable!()};
  let mut host=flow::FlowHost::from_host_snapshot(source.clone()).with_history_store_factory(semio_framework_artifact_flow_flow::FLOW_HISTORY_STORE_FACTORY);host.set_neuron_kind_info_map(Arc::clone(&infos));host.begin_gesture();let mut edit=semio_s_artifact_flow_flow_inferences::editor::flow::edit_rules::ContentEdit::new(crate::schema::flow_content_snapshot_from_working(&source.widgets,&source.synapses,&source.layout));
  match request{
   flow::FlowAuthoringRequest::ConnectPorts{from,from_port,to,to_port}=>{host.connect_ports(from,from_port,to,to_port).unwrap();for leaf in &host.pending_leaves{if let CoreMutation::AddSynapse(add)=leaf{let s=&add.synapse;edit.connect(FlowEdge{id:s.id.clone(),from:PortRef{node:s.from.clone(),port:s.from_port.clone()},to:PortRef{node:s.to.clone(),port:s.to_port.clone()},kind:"data".into()})}}},
   flow::FlowAuthoringRequest::Disconnect{id}=>{host.disconnect(id).unwrap();edit.remove_edge(id);},
   flow::FlowAuthoringRequest::RemoveWidget{id}=>{host.remove_widget(id).unwrap();edit.remove(&[id.into()],&[]);},
   flow::FlowAuthoringRequest::AddWidget{descriptor,x,y}=>{host.add_widget_descriptor(descriptor,x,y).unwrap();let CoreMutation::AddWidget(add)=&host.pending_leaves[0]else{panic!("genuine add starts with widget")};let node=crate::schema::flow_content_node_from_working(&add.widget,Some(&WidgetLayout{x,y}));edit.leaves.push(SemioFlowMutation::InsertNode(m::insert_node::InsertNode::new(node)));},
   flow::FlowAuthoringRequest::InsertPort{id,input,index}=>{if input{host.add_input_port(id,index).unwrap()}else{host.add_output_port(id,index).unwrap()}let Widget::Neuron{input_ports,output_ports,..}=host.host_snapshot.widgets.iter().find(|widget|semio_framework_artifact_flow_flow::widget_id_for(widget)==id).unwrap()else{panic!("genuine variadic widget")};edit.insert_port(id,input,index,if input{input_ports}else{output_ports});},
   flow::FlowAuthoringRequest::Reorganize{options}=>{let mut progress=|_|true;let mut control=infinite_canvas::board::schema::layout::LayoutControl::new(u64::MAX,&mut progress);host.reorganize(options,&mut control).unwrap();for widget in &host.host_snapshot.widgets{let id=semio_framework_artifact_flow_flow::widget_id_for(widget);if let Some(layout)=host.host_snapshot.layout.get(id){edit.set_position(id,layout.x,layout.y);}}},
   _=>unreachable!()
  }
  for(items,copy,calls)in[(1,4096,10000),(512,32768,200)]{for cancel in [None,Some(0),Some(1),Some(7),Some(17),Some(50)]{
   let g=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:4096};let mut caller=OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128*1024*1024,maximum_capacity_bytes:256*1024*1024,maximum_release_bytes:512*1024*1024,maximum_depth:4096},clock,1500,32768);let mut decoder=OriginalJobDecodeOwner::empty();native(&mut caller,&mut decoder,g,|_|Ok(()));let mut authoring=flow::FlowAuthoringWork::new(flow::FlowAuthoringSerials::default());let mut leaves=None;
   for turn in 0..calls{leaves=native(&mut caller,&mut decoder,g,|cx|authoring.step(&source,&infos,request,cx));if leaves.is_some(){break}assert!(turn+1<calls,"core authoring opportunity exhausted for {operation}")}
   authoring.begin_close();for turn in 0..10000{if authoring.terminal_is_empty(){break}native(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=authoring.next_close_demands(g.maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|authoring.close_step(grant))?;Ok(())}));assert!(turn+1<10000)}assert!(authoring.terminal_is_empty());drop(authoring);
   let outcome=leaves.unwrap();let mut work=FlowLeafWork::new(outcome.result.unwrap(),mode);let mut output=None;
   for turn in 0..calls{if cancel==Some(turn){caller.cancel().cancel_now();assert!(native(&mut caller,&mut decoder,g,|cx|work.step(&source,cx)).is_none());assert_eq!(caller.receipt(),Default::default());break}native(&mut caller,&mut decoder,RetainedCloneGrant{maximum_items:0,..g},|cx|work.step(&source,cx));assert_eq!(caller.receipt(),Default::default());output=native(&mut caller,&mut decoder,g,|cx|work.step(&source,cx));if output.is_some(){break}assert!(turn+1<calls,"native child mapper opportunity exhausted for {operation}")}
   if let Some(output)=output{assert_eq!(output,edit.leaves,"{operation}");for leaf in &output{if let SemioFlowMutation::SetNodeParam(param)=leaf{if matches!(param.key.as_str(),"inputPorts"|"outputPorts"){let values:Vec<String>=serde_json::from_str(&param.value).unwrap();assert_eq!(serde_json::to_string(&values).unwrap(),param.value)}}}work.restore_output(output)}else{assert!(cancel.is_some())}
   work.begin_close();for turn in 0..10000{if work.terminal_is_empty(){break}native(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=work.close_demands(g.maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|work.close_step(grant))?;Ok(())}));assert!(turn+1<10000)}assert!(work.terminal_is_empty());drop(work);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(g.maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
  }}
  assert!(host.retire_cold().is_ok());edit.content.retire_cold();edit.leaves.retire_cold();source.retire_cold();let Ok(infos)=Arc::try_unwrap(infos)else{panic!("genuine catalogue alias remains")};infos.retire_cold();
 }
}
